Definition w4rel (L pt b st : Z) : Prop :=
  (st = 0 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b <= 64 /\ (8 <= pt -> b <= 8))) \/
  (st = 3 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b < 2^31)).

(* [comment removed for export] *)
Ltac kxg_vals :=
  repeat match goal with
  | |- context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H := fresh "HR" in kx_range (EVar j) H; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in |- *; clearbody w ]
  end;
  repeat match goal with
  | |- context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H := fresh "HR" in kx_range e H; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in |- *; clearbody w ]
  end.
Ltac kxg_hyp H :=
  repeat match type of H with
  | context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H' := fresh "HR" in kx_range (EVar j) H'; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w ]
  end;
  repeat match type of H with
  | context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H' := fresh "HR" in kx_range e H'; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w ]
  end.
Ltac kxg_clear :=
  lazymatch goal with
  | HK : know_ok _ ?E _ _ |- _ =>
      let b := eval unfold E in E in
      repeat match goal with H : context [E] |- _ => clear H end;
      try clear E;
      lazymatch b with kx_env _ ?xs => try clear xs | _ => idtac end
  end.

Ltac w4s31e_post K C232 P mm :=
  kx_post_regs_keep;
  let MU := fresh "MU" in let WM := fresh "WM" in
  pose proof (munch_refl [(P + 232, P + 240)] mm) as MU;
  pose proof (wmono_refl asegs mm) as WM;
  kx_munch_wins MU [(P + 232, 8)];
  kx_cellz C232;
  kx_post_mem_free;
  lazymatch goal with |- context [mem_denot ?E mm ?l] => let EM := fresh "EM" in remember (mem_denot E mm l) as mm' eqn:EM; clear EM end;
  kxg_hyp C232; kxg_vals; kxg_clear;
  eapply K; [ exact MU | exact WM | eassumption | exact C232 | .. ].

